<?php
declare(strict_types=1);
namespace App\Services;
use App\Config\Database;
use App\Support\Reference;
use PDO;
use RuntimeException;

final class DocumentEpodService{
 private const TYPES=['waybill','bill_of_lading','delivery_note','customs','inspection','delivery_evidence','other'];
 private const RESULTS=['delivered','partial','damaged','refused'];
 private static function tripSql():string{return"SELECT tr.*,sh.shipment_ref,sh.customer_company_id,sh.current_status shipment_status,sh.load_id,l.load_ref,l.cargo_summary,d.user_id driver_user_id,tk.registration_number,oa.city origin_city,da.city destination_city FROM trips tr JOIN shipments sh ON sh.shipment_id=tr.shipment_id JOIN loads l ON l.load_id=sh.load_id JOIN drivers d ON d.driver_id=tr.driver_id JOIN trucks tk ON tk.truck_id=tr.truck_id JOIN addresses oa ON oa.address_id=tr.origin_address_id JOIN addresses da ON da.address_id=tr.destination_address_id";}
 public static function trip(int$id,int$uid):?array{$st=Database::connection()->prepare(self::tripSql()." WHERE tr.trip_id=?");$st->execute([$id]);$r=$st->fetch();return$r&&self::canView($r,$uid)?$r:null;}
 private static function canView(array$r,int$uid):bool{
  if(Auth::can('DOCUMENT_VIEW_OPERATIONS')||Auth::can('EPOD_REVIEW_OPERATIONS'))return true;
  if((Auth::can('DOCUMENT_VIEW_DRIVER')||Auth::can('EPOD_VIEW_DRIVER'))&&(int)$r['driver_user_id']===$uid)return true;
  if(Auth::can('DOCUMENT_VIEW_SHIPPER')||Auth::can('EPOD_VIEW_SHIPPER'))foreach(Auth::context()['companies']??[]as$c)if((int)$c['company_id']===(int)$r['customer_company_id'])return true;
  if(Auth::can('DOCUMENT_VIEW_CARRIER')||Auth::can('EPOD_VIEW_CARRIER')){$p=CarrierOnboarding::current($uid);if($p&&(($p['owner_type']==='company'&&(int)$r['carrier_company_id']===(int)$p['subject_id'])||($p['owner_type']==='individual'&&(int)$r['carrier_user_id']===$uid)))return true;}
  return false;
 }
 private static function requireTrip(int$id,int$uid):array{$r=self::trip($id,$uid);if(!$r)throw new RuntimeException('Trip not found or access denied.');return$r;}
 public static function operationsQueue():array{if(!Auth::can('EPOD_REVIEW_OPERATIONS'))throw new RuntimeException('Operations e-POD permission required.');$sql=str_replace(' FROM trips tr',',e.epod_status FROM trips tr',self::tripSql());return Database::connection()->query($sql." LEFT JOIN epods e ON e.trip_id=tr.trip_id WHERE sh.current_status='delivered_pending_epod' OR e.epod_status IN('submitted','rejected') ORDER BY tr.delivered_at DESC")->fetchAll();}
 public static function documents(int$tripId,int$uid):array{$r=self::requireTrip($tripId,$uid);$visibility=Auth::can('DOCUMENT_VIEW_OPERATIONS')?'1=1':"td.visibility_scope IN('involved_parties','".(Auth::hasRole('SHIPPER')?'shipper':(Auth::hasRole('TRUCK_OWNER')?'carrier':'driver'))."')";$st=Database::connection()->prepare("SELECT d.*,dv.document_version_id,dv.original_file_name,dv.mime_type,dv.byte_size,dv.checksum_sha256,dv.uploaded_at,u.display_name uploaded_by FROM trip_documents td JOIN documents d ON d.document_id=td.document_id JOIN document_versions dv ON dv.document_version_id=d.current_version_id LEFT JOIN users u ON u.user_id=d.created_by_user_id WHERE td.subject_id=? AND td.status='active' AND d.status='active' AND {$visibility} ORDER BY d.created_at DESC");$st->execute([$tripId]);return$st->fetchAll();}
 public static function upload(int$tripId,array$data,array$file,int$uid):int{
  $r=self::requireTrip($tripId,$uid);$driver=Auth::can('DOCUMENT_UPLOAD_DRIVER')&&(int)$r['driver_user_id']===$uid;$ops=Auth::can('DOCUMENT_MANAGE_OPERATIONS');if(!$driver&&!$ops)throw new RuntimeException('Document upload permission required.');
  $type=(string)($data['document_type']??'other');if(!in_array($type,self::TYPES,true))throw new RuntimeException('Invalid document type.');
  [$key,$name,$mime,$size,$hash]=self::store($file);$pdo=Database::connection();$pdo->beginTransaction();
  try{$visibility=$ops?(string)($data['visibility_scope']??'involved_parties'):'involved_parties';if(!in_array($visibility,['involved_parties','operations_only','shipper','carrier','driver'],true))$visibility='involved_parties';
   $pdo->prepare("INSERT INTO documents(document_ref,title,owner_company_id,owner_user_id,document_type,classification,sensitivity,description,status,created_by_user_id,updated_by_user_id) VALUES(?,?,?,?,?,'transport',?,?, 'active',?,?)")->execute([Reference::make('DOC'),trim((string)($data['title']??''))?:$name,$r['customer_company_id'],$uid,$type,$visibility==='operations_only'?'restricted':'normal',trim((string)($data['description']??''))?:null,$uid,$uid]);$did=(int)$pdo->lastInsertId();
   $pdo->prepare("INSERT INTO document_versions(document_version_ref,document_id,version_no,original_file_name,storage_object_key,checksum_sha256,mime_type,byte_size,uploaded_at,status,created_by_user_id,updated_by_user_id) VALUES(?,?,1,?,?,?,?,?,UTC_TIMESTAMP(6),'active',?,?)")->execute([Reference::make('DOV'),$did,$name,$key,$hash,$mime,$size,$uid,$uid]);$vid=(int)$pdo->lastInsertId();
   $pdo->prepare("UPDATE documents SET current_version_id=? WHERE document_id=?")->execute([$vid,$did]);
   $pdo->prepare("INSERT INTO trip_documents(trip_document_ref,document_id,subject_id,link_role,visibility_scope,status,created_by_user_id,updated_by_user_id) VALUES(?,?,?,?,?,'active',?,?)")->execute([Reference::make('TDO'),$did,$tripId,$type,$visibility,$uid,$uid]);
   $pdo->prepare("INSERT INTO shipment_documents(shipment_document_ref,document_id,subject_id,link_role,visibility_scope,status,created_by_user_id,updated_by_user_id) VALUES(?,?,?,?,?,'active',?,?)")->execute([Reference::make('SDO'),$did,$r['shipment_id'],$type,$visibility,$uid,$uid]);
   self::audit($pdo,'TRANSPORT_DOCUMENT_UPLOADED',$tripId,$uid,['document_id'=>$did,'document_type'=>$type]);$pdo->commit();return$did;
  }catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();@unlink(BASE_PATH.'/'.$key);throw$e;}
 }
 private static function store(array$f):array{
  if(($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new RuntimeException('Choose a file to upload.');
  $size=(int)($f['size']??0);if($size<1||$size>10485760)throw new RuntimeException('File must be between 1 byte and 10 MB.');
  $tmp=(string)$f['tmp_name'];$mime=(new \finfo(FILEINFO_MIME_TYPE))->file($tmp)?:'';$allowed=['application/pdf'=>'pdf','image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime]))throw new RuntimeException('Only PDF, JPG, PNG and WebP files are allowed.');
  $dir=BASE_PATH.'/storage/uploads/documents/'.gmdate('Y/m');if(!is_dir($dir)&&!mkdir($dir,0770,true)&&!is_dir($dir))throw new RuntimeException('Upload storage is unavailable.');
  $name=basename((string)($f['name']??'document'));$key='storage/uploads/documents/'.gmdate('Y/m').'/'.bin2hex(random_bytes(20)).'.'.$allowed[$mime];$dest=BASE_PATH.'/'.$key;if(!move_uploaded_file($tmp,$dest))throw new RuntimeException('The file could not be stored.');return[$key,$name,$mime,$size,hash_file('sha256',$dest)];
 }
 public static function document(int$id,int$uid):?array{$st=Database::connection()->prepare("SELECT d.*,dv.storage_object_key,dv.original_file_name,dv.mime_type,dv.byte_size,td.subject_id trip_id,td.visibility_scope FROM documents d JOIN document_versions dv ON dv.document_version_id=d.current_version_id JOIN trip_documents td ON td.document_id=d.document_id WHERE d.document_id=? AND d.status='active' LIMIT 1");$st->execute([$id]);$d=$st->fetch();if(!$d||!self::trip((int)$d['trip_id'],$uid))return null;if(Auth::can('DOCUMENT_VIEW_OPERATIONS')||$d['visibility_scope']==='involved_parties')return$d;$role=Auth::hasRole('SHIPPER')?'shipper':(Auth::hasRole('TRUCK_OWNER')?'carrier':(Auth::hasRole('DRIVER')?'driver':''));return$d['visibility_scope']===$role?$d:null;}
 public static function epod(int$tripId,int$uid):?array{$r=self::requireTrip($tripId,$uid);$st=Database::connection()->prepare("SELECT e.*,ev.version_no,ev.delivery_notes,ev.signature_name,ev.submitted_by_user_id,u.display_name submitted_by_name FROM epods e LEFT JOIN epod_versions ev ON ev.epod_version_id=e.active_version_id LEFT JOIN users u ON u.user_id=ev.submitted_by_user_id WHERE e.trip_id=? LIMIT 1");$st->execute([$tripId]);$e=$st->fetch();if(!$e)return null;$st=Database::connection()->prepare("SELECT * FROM epod_confirmations WHERE epod_id=? ORDER BY confirmed_at,epod_confirmation_id");$st->execute([$e['epod_id']]);$e['confirmations']=$st->fetchAll();return$e;}
 public static function submitEpod(int$tripId,array$d,int$uid):void{
  $r=self::requireTrip($tripId,$uid);$driver=Auth::can('EPOD_SUBMIT_DRIVER')&&(int)$r['driver_user_id']===$uid;$ops=Auth::can('EPOD_REVIEW_OPERATIONS');if(!$driver&&!$ops)throw new RuntimeException('e-POD submission permission required.');if($r['current_status']!=='delivered'||$r['shipment_status']!=='delivered_pending_epod')throw new RuntimeException('e-POD may be submitted only after delivery.');
  $result=(string)($d['delivery_result']??'');$recipient=trim((string)($d['recipient_name']??''));$signature=trim((string)($d['signature_name']??''));if(!in_array($result,self::RESULTS,true)||$recipient===''||$signature==='')throw new RuntimeException('Delivery result, recipient and signature name are required.');$delivered=self::dateValue((string)($d['delivered_at']??''));
  $pdo=Database::connection();$pdo->beginTransaction();try{$st=$pdo->prepare("SELECT td.document_id FROM trip_documents td WHERE td.subject_id=? AND td.link_role='delivery_evidence' AND td.status='active'");$st->execute([$tripId]);$evidence=$st->fetchAll(PDO::FETCH_COLUMN);if(!$evidence)throw new RuntimeException('Upload at least one delivery-evidence file before submitting e-POD.');$st=$pdo->prepare("SELECT * FROM epods WHERE trip_id=? FOR UPDATE");$st->execute([$tripId]);$e=$st->fetch();if($e&&in_array($e['epod_status'],['submitted','confirmed'],true))throw new RuntimeException('This e-POD is already awaiting review or confirmed.');
   if(!$e){$st=$pdo->prepare("SELECT stop_id FROM stops WHERE trip_id=? AND stop_type='destination' AND status='active' ORDER BY sequence_no DESC LIMIT 1");$st->execute([$tripId]);$stop=(int)$st->fetchColumn();$pdo->prepare("INSERT INTO epods(epod_ref,shipment_id,trip_id,stop_id,driver_id,epod_status,delivered_at,delivery_result,recipient_name,recipient_contact,submitted_at,submitted_by_user_id,refusal_flag,exception_flag,status,created_by_user_id,updated_by_user_id) VALUES(?,?,?,?,?,'submitted',?,?,?,?,UTC_TIMESTAMP(6),?,?,?,'active',?,?)")->execute([Reference::make('EPD'),$r['shipment_id'],$tripId,$stop,$r['driver_id'],$delivered,$result,$recipient,trim((string)($d['recipient_contact']??''))?:null,$uid,$result==='refused'?1:0,in_array($result,['partial','damaged','refused'],true)?1:0,$uid,$uid]);$eid=(int)$pdo->lastInsertId();$version=1;}else{$eid=(int)$e['epod_id'];$st=$pdo->prepare("SELECT COALESCE(MAX(version_no),0)+1 FROM epod_versions WHERE epod_id=?");$st->execute([$eid]);$version=(int)$st->fetchColumn();$pdo->prepare("UPDATE epods SET epod_status='submitted',delivered_at=?,delivery_result=?,recipient_name=?,recipient_contact=?,submitted_at=UTC_TIMESTAMP(6),submitted_by_user_id=?,confirmed_at=NULL,confirmed_by_user_id=NULL,updated_by_user_id=?,row_version=row_version+1 WHERE epod_id=?")->execute([$delivered,$result,$recipient,trim((string)($d['recipient_contact']??''))?:null,$uid,$uid,$eid]);}
   $pdo->prepare("INSERT INTO epod_versions(epod_version_ref,epod_id,version_no,delivery_result,recipient_name,recipient_contact,delivery_notes,signature_name,delivered_at,submitted_by_user_id,metadata_json,status,created_by_user_id,updated_by_user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,'active',?,?)")->execute([Reference::make('EPV'),$eid,$version,$result,$recipient,trim((string)($d['recipient_contact']??''))?:null,trim((string)($d['delivery_notes']??''))?:null,$signature,$delivered,$uid,json_encode(['phase'=>10]),$uid,$uid]);$vid=(int)$pdo->lastInsertId();$pdo->prepare("UPDATE epods SET active_version_id=? WHERE epod_id=?")->execute([$vid,$eid]);$link=$pdo->prepare("INSERT IGNORE INTO epod_documents(epod_document_ref,document_id,subject_id,link_role,visibility_scope,status,created_by_user_id,updated_by_user_id) VALUES(?,?,?,'delivery_evidence','involved_parties','active',?,?)");foreach($evidence as$documentId)$link->execute([Reference::make('EDO'),$documentId,$eid,$uid,$uid]);self::history($pdo,'epod',$eid,$e['epod_status']??null,'submitted',$uid,'Electronic proof of delivery submitted');self::audit($pdo,'EPOD_SUBMITTED',$tripId,$uid,['epod_id'=>$eid,'version_id'=>$vid,'evidence_documents'=>count($evidence)]);NotificationService::send($pdo,NotificationService::usersForRole($pdo,'MCCOLLIN_OPERATIONS'),'epod','e-POD submitted','An e-POD is awaiting Operations review.','documents/trip.php?id='.$tripId,'epod',$eid,$uid,'high');$pdo->commit();
  }catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}
 }
 public static function reviewEpod(int$tripId,string$decision,string$notes,int$uid):void{
  if(!Auth::can('EPOD_REVIEW_OPERATIONS')||!in_array($decision,['confirmed','rejected'],true))throw new RuntimeException('Operations e-POD review permission required.');$r=self::requireTrip($tripId,$uid);if($decision==='rejected'&&trim($notes)==='')throw new RuntimeException('A rejection reason is required.');$pdo=Database::connection();$pdo->beginTransaction();try{$st=$pdo->prepare("SELECT * FROM epods WHERE trip_id=? FOR UPDATE");$st->execute([$tripId]);$e=$st->fetch();if(!$e||$e['epod_status']!=='submitted')throw new RuntimeException('Only a submitted e-POD may be reviewed.');$pdo->prepare("INSERT INTO epod_confirmations(epod_confirmation_ref,epod_id,epod_version_id,decision,confirmation_notes,confirmed_at,confirmed_by_user_id,status,created_by_user_id,updated_by_user_id) VALUES(?,?,?,?,?,UTC_TIMESTAMP(6),?,'active',?,?)")->execute([Reference::make('EPC'),$e['epod_id'],$e['active_version_id'],$decision,trim($notes)?:null,$uid,$uid,$uid]);$extra=$decision==='confirmed'?",confirmed_at=UTC_TIMESTAMP(6),confirmed_by_user_id=".(int)$uid:'';$pdo->exec("UPDATE epods SET epod_status=".$pdo->quote($decision).$extra.",updated_by_user_id=".(int)$uid.",row_version=row_version+1 WHERE epod_id=".(int)$e['epod_id']);
   if($decision==='confirmed'){$pdo->prepare("UPDATE shipments SET current_status='delivered',updated_by_user_id=?,row_version=row_version+1 WHERE shipment_id=? AND current_status='delivered_pending_epod'")->execute([$uid,$r['shipment_id']]);$pdo->prepare("UPDATE loads SET current_status='delivered',updated_by_user_id=?,row_version=row_version+1 WHERE load_id=? AND current_status='delivered_pending_epod'")->execute([$uid,$r['load_id']]);$pdo->prepare("INSERT INTO shipment_milestones(shipment_milestone_ref,shipment_id,trip_id,milestone_code,occurred_at,actor_user_id,metadata_json,status,created_by_user_id,updated_by_user_id) VALUES(?,?,?,'epod_confirmed',UTC_TIMESTAMP(6),?,?,'active',?,?)")->execute([Reference::make('MIL'),$r['shipment_id'],$tripId,$uid,json_encode(['epod_id'=>(int)$e['epod_id']]),$uid,$uid]);}
   self::history($pdo,'epod',(int)$e['epod_id'],'submitted',$decision,$uid,'Electronic proof of delivery reviewed');self::audit($pdo,'EPOD_'.strtoupper($decision),$tripId,$uid,['epod_id'=>(int)$e['epod_id']]);NotificationService::tripEvent($pdo,$tripId,'e-POD '.$decision,'Electronic proof of delivery was '.$decision.'.',$uid,$decision==='rejected'?'high':'normal');$pdo->commit();
  }catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}
 }
 private static function dateValue(string$v):string{$t=strtotime($v);if(!$t)throw new RuntimeException('Enter a valid delivery date and time.');return gmdate('Y-m-d H:i:s',$t);}
 private static function history(PDO$p,string$e,int$i,?string$o,string$n,int$u,string$r):void{$role=null;foreach(Auth::context()['roles']??[]as$x)if(in_array($x['role_code'],['MCCOLLIN_OPERATIONS','DRIVER'],true)){$role=(int)$x['user_role_id'];break;}$p->prepare("INSERT INTO status_history(status_history_ref,entity_type,entity_id_value,previous_status,new_status,actor_user_id,actor_user_role_id,source_channel,reason,occurred_at,status,created_by_user_id) VALUES(?,?,?,?,?,?,?,'web',?,UTC_TIMESTAMP(6),'active',?)")->execute([Reference::make('STH'),$e,$i,$o,$n,$u,$role,$r,$u]);}
 private static function audit(PDO$p,string$a,int$t,int$u,array$x):void{$p->prepare("INSERT INTO audit_events(audit_event_ref,metadata_json,status,created_by_user_id) VALUES(?,?,'active',?)")->execute([Reference::make('AUD'),json_encode(array_merge(['action_code'=>$a,'trip_id'=>$t],$x)),$u]);}
}